<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use App\Modules\Tourism\Services\TourismDestinationService;use RuntimeException;use Throwable;
final class TourismDestinationController extends Controller{private TourismDestinationService $s;private Authorization $a;public function __construct(){$this->s=new TourismDestinationService();$this->a=new Authorization();}private function allow(string $p,string $r='/tourism'):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}public function index():void{if(!$this->allow('tourism.destinations.view'))return;$t=(int)Auth::tenantId();$trash=($_GET['view']??'')==='trash';$this->view('Tourism::Destinations.index',['title'=>$trash?'Deleted Destinations':'Tourism Destinations','destinations'=>$this->s->all($t,$trash),'trash'=>$trash]);}public function create():void{if(!$this->allow('tourism.destinations.create','/tourism/destinations'))return;$this->view('Tourism::Destinations.create',['title'=>'Add Destination','locations'=>$this->s->locations()]);}public function store():void{if(!$this->allow('tourism.destinations.create','/tourism/destinations'))return;$t=(int)Auth::tenantId();try{$id=$this->s->create($t,$_POST,(int)Auth::id());flash('success','Tourism destination created successfully.');redirect('/tourism/destinations/'.$id);}catch(Throwable $e){$this->view('Tourism::Destinations.create',['title'=>'Add Destination','locations'=>$this->s->locations(),'error'=>$e->getMessage(),'old'=>$_POST]);}}public function show(int $id):void{if(!$this->allow('tourism.destinations.view','/tourism/destinations'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('Tourism::Destinations.show',['title'=>$r['name'],'record'=>$r]);}public function edit(int $id):void{if(!$this->allow('tourism.destinations.edit','/tourism/destinations'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('Tourism::Destinations.edit',['title'=>'Edit Destination','record'=>$r,'locations'=>$this->s->locations()]);}public function update(int $id):void{if(!$this->allow('tourism.destinations.edit','/tourism/destinations'))return;$t=(int)Auth::tenantId();try{$this->s->update($t,$id,$_POST,(int)Auth::id());flash('success','Destination updated successfully.');redirect('/tourism/destinations/'.$id);}catch(Throwable $e){$r=$this->s->find($t,$id)??$_POST;$this->view('Tourism::Destinations.edit',['title'=>'Edit Destination','record'=>$r,'locations'=>$this->s->locations(),'error'=>$e->getMessage()]);}}public function destroy(int $id):void{if(!$this->allow('tourism.destinations.delete','/tourism/destinations'))return;try{$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Destination moved to Trash.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/destinations');}public function restore(int $id):void{if(!$this->allow('tourism.destinations.delete','/tourism/destinations?view=trash'))return;try{$this->s->restore((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Destination restored.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/destinations?view=trash');}}
